    private static Geometry Frozen(string data)
    {
        var geometry = Geometry.Parse(data);
        geometry.Freeze();
        return geometry;
    }

    private static Geometry Outline(Geometry geometry, double thickness, PenLineJoin join)
    {
        // SVG strokes use a miter limit of 4; the default flattening tolerance turns a 24px lens into a polygon.
        var outline = geometry.GetWidenedPathGeometry(new Pen(null, thickness) { LineJoin = join, MiterLimit = 4 },
            0.005, ToleranceType.Absolute);
        outline.Freeze();
        return outline;
    }

    private static Geometry Group(params Geometry[] children)
    {
        var geometry = new GeometryGroup();
        foreach (var child in children) geometry.Children.Add(child);
        geometry.Freeze();
        return geometry;
    }
